  checkLocalDB() {
    let query =
      "SELECT * FROM cwsn_student_list" +
      ' WHERE school_key_id = "' +
      this.schlId +
      '"' +
      ' And StuId = "' +
      this.studentId +
      '"';
    // debugger
    this.sqliteDB.executeQuery(query).then((res) => {
      this.form.reset();
      if (res.rows.length > 0) {
        // this.clustoers=[];
        let value: any = {};
        value = res.rows.item(0);
        this.stdDetails = res.rows.item(0);
        let type: any = "None";
        this.referFromHealth = this.stdDetails.cwsnStatus;
        if (this.referFromHealth == 1) {
          type = "Existing CWSN";
        } else if (this.referFromHealth == 2) {
          type = "Directly identified by special educator";
        } else if (this.referFromHealth == 3) {
          type = "Referred from Health Module";
        }
        //  else if(value.Status == 4){
        //   type = 'Referred from PMOA';
        // };
        this.differently_abled = value.differently_abled
          ? value.differently_abled
          : "";
        this.showFormValues = true;
        if (
          this.differently_abled == "0" ||
          this.differently_abled == "99" ||
          this.referFromHealth != 1
        ) {
          this.showFormValues = false;
        }
        value.Status = type;
        this.form.patchValue(value);
        // console.log('after patch', this.form)
        this.form.updateValueAndValidity();
      } else {
        this.getStudentDetails(this.studentId);
      }
    });
  }

  initialValidator() {
    this.form = this.formBuilder.group({
      nid: new FormControl(null, [Validators.pattern(this.nidNumberPattern)]),
      udid: new FormControl(null, [Validators.pattern(this.udidNumberPattern)]),
      unique_id_no: new FormControl(null),
      da_name: new FormControl(null),
      Status: new FormControl(null),
      IndexId: new FormControl(null),
      ScreenedDate: new FormControl(null),
    });
  }

  getStudentDetails(id) {
    this.cwsnService
      .getEachStudentDetails(id, this.schlId)
      .subscribe((data) => {
        if (data.dataStatus) {
          let sqlArray = [];
          data.result.forEach((element) => {
            sqlArray.push([
              "INSERT INTO cwsn_student_list VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?)",
              [
                null,
                element.school_id,
                element.id,
                element.nid,
                element.udid,
                element.IndexId,
                element.user_id,
                element.differently_abled,
                element.ScreenedDate,
                element.Status,
                element.da_name,
                element.userId,
                3,
                "",
              ],
            ]);
          });
          this.sqliteDB.bulkInsert(sqlArray).then((insertres) => {
            this.checkLocalDB();
          });
        } else {
          this.alertService.warning("No data Found");
        }
      });
  }

  onSync() {
    let query =
      "DELETE FROM cwsn_student_list" +
      ' WHERE school_key_id = "' +
      this.schlId +
      '"' +
      ' And StuId = "' +
      this.studentId +
      '"';
    this.sqliteDB.executeQuery(query).then((res) => {
      if (res) {
        this.checkLocalDB();
      }
    });
  }

